pm.test("El status code es 200", function () {
    pm.response.to.have.status(200);
});

pm.test("La respuesta contiene una lista de productos", function () {
    const body = pm.response.json();

    pm.expect(body.products).to.be.an("array");
    pm.expect(body.products.length).to.be.above(0);
});

pm.test("Los productos tienen la estructura esperada", function () {
    const body = pm.response.json();

    body.products.forEach(function (product) {
        pm.expect(product).to.have.property("id");
        pm.expect(product.id).to.be.a("number");

        pm.expect(product).to.have.property("title");
        pm.expect(product.title).to.be.a("string");

        pm.expect(product).to.have.property("price");
        pm.expect(product.price).to.be.a("number");
    });
});

pm.test("La paginación tiene la estructura correcta", function () {
    const body = pm.response.json();

    pm.expect(body.total).to.be.a("number");
    pm.expect(body.skip).to.be.a("number");
    pm.expect(body.limit).to.be.a("number");
});

pm.test("El status code es 200", function () {
    pm.response.to.have.status(200);
});

pm.test("La respuesta contiene un token", function () {
    const body = pm.response.json();

    pm.expect(body.accessToken).to.be.a("string");
    pm.expect(body.accessToken).to.not.be.empty;
});

pm.test("La respuesta contiene datos del usuario", function () {
    const body = pm.response.json();

    pm.expect(body).to.have.property("id");
    pm.expect(body).to.have.property("username", "emilys");
});

pm.test("El status code es 400", function () {
    pm.response.to.have.status(400);
});

pm.test("Se informa el error de autenticación", function () {
    const body = pm.response.json();

    pm.expect(body).to.have.property("message");
    pm.expect(body.message).to.be.a("string");
    pm.expect(body.message.length).to.be.above(0);
});

pm.test("No se devuelve un token de acceso", function () {
    const body = pm.response.json();

    pm.expect(body.accessToken).to.be.undefined;
});
